/* Acct01Mapper.countUserSiteAuth */
SELECT
    COUNT(1)
FROM TB_USER_SITE_AUTH A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'

/* Acct01Mapper.selectAcctList */
SELECT

FROM TB_ACCT A

WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.DEL_YN = 'N'
  AND A.USE_YN = 'Y'

    AND A.SITE_CD = #{siteCd}


    AND A.ACCT_GRADE_CD = #{acctGradeCd}


    AND A.PROCESS_STATUS_CD = #{processStatusCd}


    AND A.OCCUR_YMD >= REPLACE(#{startDate}, '-', '')


    AND A.OCCUR_YMD <= REPLACE(#{endDate}, '-', '')


    AND (
        (A.VICTIM_USER_TYPE_CD = 'REGULAR' AND RU.USER_NM LIKE CONCAT('%', #{searchKeyword}, '%'))
     OR (A.VICTIM_USER_TYPE_CD = 'DAILY'   AND DU.USER_NM LIKE CONCAT('%', #{searchKeyword}, '%'))
     OR A.OCCUR_PLACE LIKE CONCAT('%', #{searchKeyword}, '%')
    )

ORDER BY A.OCCUR_YMD DESC, A.OCCUR_TIME DESC, A.ACCT_ID DESC

/* Acct01Mapper.selectAcctInfo */
SELECT

FROM TB_ACCT A

WHERE A.CMPNY_CD = #{gvCmpnyCd}
