/* Acct01Mapper.selectAcctHeader */
SELECT

FROM TB_ACCT A

WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.ACCT_ID = #{acctId}
  AND A.DEL_YN = 'N'
