/* Acct01Mapper.selectNextAcctId */
SELECT
    CONCAT(
        'ACC'
      , #{occurYmd}
      , LPAD(
            IFNULL(
                MAX(CAST(SUBSTR(A.ACCT_ID, 12, 4) AS UNSIGNED))
              , 0
            ) + 1
          , 4, '0'
        )
    )
FROM TB_ACCT A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.ACCT_ID LIKE CONCAT('ACC', #{occurYmd}, '%')

