/* Acct01Mapper.insertAcct */
INSERT INTO TB_ACCT
(
    CMPNY_CD
  , SITE_CD
  , ACCT_ID
  , VICTIM_USER_TYPE_CD
  , VICTIM_USER_CD
  , OCCUR_YMD
  , OCCUR_TIME
  , OCCUR_PLACE
  , ACCT_GRADE_CD
  , ACCT_DESC
  , EMPLOYER_DESC
  , PROCESS_STATUS_CD
  , USE_YN
  , DEL_YN
  , INSERT_NO
  , INSERT_DATE
)
VALUES
(
    #{gvCmpnyCd}
  , #{siteCd}
  , #{acctId}
  , #{victimUserTypeCd}
  , #{victimUserCd}
  , #{occurYmd}
  , #{occurTime}
  , #{occurPlace}
  , #{acctGradeCd}
  , #{acctDesc}
  , #{employerDesc}
  , '100'
  , 'Y'
  , 'N'
  , #{gvUserCd}
  , NOW()
)

mapper.update:
/* Acct01Mapper.updateAcct */
UPDATE TB_ACCT
SET
    OCCUR_YMD         = #{occurYmd}
  , OCCUR_TIME        = #{occurTime}
  , OCCUR_PLACE       = #{occurPlace}
  , ACCT_GRADE_CD = #{acctGradeCd}
  , ACCT_DESC     = #{acctDesc}
  , EMPLOYER_DESC     = #{employerDesc}

  , PROCESS_STATUS_CD = #{processStatusCd}

  , UPDATE_NO         = #{gvUserCd}
  , UPDATE_DATE       = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND ACCT_ID = #{acctId}
  AND DEL_YN = 'N'

/* Acct01Mapper.deleteAcct */
UPDATE TB_ACCT
SET
    DEL_YN      = 'Y'
  , UPDATE_NO   = #{gvUserCd}
  , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND ACCT_ID = #{acctId}
  AND DEL_YN = 'N'

mapper.select:
/* Acct01Mapper.selectVictimList */
SELECT 'REGULAR' AS userTypeCd , '정규' AS userTypeNm , RU.USER_CD AS userCd , RU.USER_ID AS userId , CASE WHEN CHAR_LENGTH(RU.USER_NM) <= 1 THEN RU.USER_NM WHEN CHAR_LENGTH(RU.USER_NM) = 2 THEN CONCAT(LEFT(RU.USER_NM, 1), '*') ELSE CONCAT(LEFT(RU.USER_NM, 2), REPEAT('*', CHAR_LENGTH(RU.USER_NM) - 2)) END AS userNm , RU.MBL_NO_LAST4 AS mblNoLast4 , RU.SITE_CD AS siteCd , ST.SITE_NM AS siteNm , ND.NODE_NM AS nodeNm FROM TB_USER RU LEFT OUTER JOIN TB_SITE ST ON (RU.CMPNY_CD = ST.CMPNY_CD AND RU.SITE_CD = ST.SITE_CD) LEFT OUTER JOIN TB_SITE_NODE ND ON (RU.CMPNY_CD = ND.CMPNY_CD AND RU.SITE_CD = ND.SITE_CD AND RU.NODE_CD = ND.NODE_CD) WHERE RU.CMPNY_CD = #{gvCmpnyCd} AND RU.USE_YN = 'Y'
AND RU.SITE_CD = #{siteCd}
AND ( RU.USER_NM LIKE CONCAT('%', #{userNm}, '%') OR RU.USER_ID LIKE CONCAT('%', #{userNm}, '%') OR RU.USER_CD LIKE CONCAT('%', #{userNm}, '%') )
UNION ALL
SELECT 'DAILY' AS userTypeCd , '일용' AS userTypeNm , DU.USER_CD AS userCd , DU.USER_ID AS userId , CASE WHEN CHAR_LENGTH(DU.USER_NM) <= 1 THEN DU.USER_NM WHEN CHAR_LENGTH(DU.USER_NM) = 2 THEN CONCAT(LEFT(DU.USER_NM, 1), '*') ELSE CONCAT(LEFT(DU.USER_NM, 2), REPEAT('*', CHAR_LENGTH(DU.USER_NM) - 2)) END AS userNm , DU.MBL_NO_LAST4 AS mblNoLast4 , DU.SITE_CD AS siteCd , ST.SITE_NM AS siteNm , NULL AS nodeNm FROM TB_DAILY_USER DU LEFT OUTER JOIN TB_SITE ST ON (DU.CMPNY_CD = ST.CMPNY_CD AND DU.SITE_CD = ST.SITE_CD) WHERE DU.CMPNY_CD = #{gvCmpnyCd} AND DU.USE_YN = 'Y'
AND DU.SITE_CD = #{siteCd}
AND ( DU.USER_NM LIKE CONCAT('%', #{userNm}, '%') OR DU.USER_ID LIKE CONCAT('%', #{userNm}, '%') OR DU.USER_CD LIKE CONCAT('%', #{userNm}, '%') )
ORDER BY userNm

/* Acct01Mapper.countVictim */
SELECT
    COUNT(1)
FROM (

    SELECT RU.USER_CD
    FROM TB_USER RU
    WHERE RU.CMPNY_CD = #{cmpnyCd}
      AND RU.SITE_CD = #{siteCd}
      AND RU.USER_CD = #{victimUserCd}
      AND RU.USE_YN = 'Y'


    SELECT DU.USER_CD
    FROM TB_DAILY_USER DU
    WHERE DU.CMPNY_CD = #{cmpnyCd}
      AND DU.SITE_CD = #{siteCd}
      AND DU.USER_CD = #{victimUserCd}
      AND DU.USE_YN = 'Y'



    SELECT NULL AS USER_CD FROM DUAL WHERE 1 = 0

) V

/* Acct01Mapper.selectPatrolSummary */
SELECT
    AN.CHKPT_CD                                                          AS chkptCd
  , MAX(TM.CHKPT_NM)                                                     AS chkptNm
  , MAX(TM.CHKLST_TYPE)                                                  AS chklstType
  , COUNT(1)                                                             AS totalCnt
  , IFNULL(SUM(CASE WHEN AN.INSPECT_ANSWER_TYPE = 'Y' THEN 1 ELSE 0 END), 0) AS goodCnt
  , IFNULL(SUM(CASE WHEN AN.INSPECT_ANSWER_TYPE = 'N' THEN 1 ELSE 0 END), 0) AS badCnt
FROM TB_CHKPT_INSPECT_ANSWER AN
     LEFT OUTER JOIN TB_CHKPT_TYPE_MGMT TM
        ON (
            AN.CMPNY_CD = TM.CMPNY_CD
        AND AN.SITE_CD = TM.SITE_CD
        AND AN.CHKPT_CD = TM.CHKPT_CD


        AND TM.CHKLST_TYPE = #{chklstType}

        )
WHERE AN.CMPNY_CD = #{gvCmpnyCd}
  AND AN.SITE_CD = #{siteCd}
  AND AN.WORK_DATE >= DATE_FORMAT(DATE_SUB(STR_TO_DATE(#{occurYmd}, '%Y%m%d'), INTERVAL 7 DAY), '%Y%m%d')
  AND AN.WORK_DATE <= #{occurYmd}

    AND AN.CHKPT_CD = #{chkptCd}

GROUP BY AN.CHKPT_CD
ORDER BY badCnt DESC, AN.CHKPT_CD

/* Acct01Mapper.selectPatrolBadItems */ SELECT AN.CHKPT_CD AS chkptCd , AN.INSPECT_ITEM_CD AS inspectItemCd , II.INSPECT_ITEM_SUBJ AS inspectItemSubj , AN.WORK_DATE AS workDate , AN.INSPECT_ANSWER_TYPE AS inspectAnswerType , AN.ANSWER_DESC AS answerDesc FROM TB_CHKPT_INSPECT_ANSWER AN LEFT OUTER JOIN TB_CHKPT_TYPE_MGMT TM ON ( AN.CMPNY_CD = TM.CMPNY_CD AND AN.SITE_CD = TM.SITE_CD AND AN.CHKPT_CD = TM.CHKPT_CD
AND TM.CHKLST_TYPE = #{chklstType}
) LEFT OUTER JOIN TB_CHKPT_INSPECT_ITEM II ON ( AN.CMPNY_CD = II.CMPNY_CD AND TM.CHKLST_TYPE = II.CHKLST_TYPE AND AN.INSPECT_ITEM_CD = II.INSPECT_ITEM_CD ) WHERE AN.CMPNY_CD = #{gvCmpnyCd} AND AN.SITE_CD = #{siteCd} AND AN.INSPECT_ANSWER_TYPE = 'N' AND AN.WORK_DATE >= DATE_FORMAT(DATE_SUB(STR_TO_DATE(#{occurYmd}, '%Y%m%d'), INTERVAL 7 DAY), '%Y%m%d') AND AN.WORK_DATE <= #{occurYmd}
AND AN.CHKPT_CD = #{chkptCd}
ORDER BY AN.WORK_DATE DESC, AN.CHKPT_CD, AN.INSPECT_ITEM_CD

/* Acct01Mapper.selectRiskList */ SELECT A.PROCESS_CD AS processCd , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'BAIM_VAL', A.PROCESS_CD, 'COM002') AS processNm , A.RISK_TYPE_CD AS riskTypeCd , RT.RISK_TYPE_NM AS riskTypeNm , A.HAZARD_CD AS hazardCd , SH.HAZARD_NM AS hazardNm , A.ASSESSMENT_CD AS assessmentCd , A.ASSESSMENT_STATUS AS assessmentStatus , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'SYST_VAL', A.ASSESSMENT_STATUS, 'SYS011') AS assessmentStatusNm , A.INIT_RISK_LV AS initRiskLv , A.REVAL_RISK_LV AS revalRiskLv , DATE_FORMAT(A.INIT_ASSESS_DATE, '%Y-%m-%d') AS initAssessDate FROM TB_RISK_ASSESSMENT A LEFT OUTER JOIN TB_RISK_TYPE RT ON (A.CMPNY_CD = RT.CMPNY_CD AND A.RISK_TYPE_CD = RT.RISK_TYPE_CD) LEFT OUTER JOIN TB_RISK_SITE_HAZARD SH ON (A.CMPNY_CD = SH.CMPNY_CD AND A.RISK_TYPE_CD = SH.RISK_TYPE_CD AND A.HAZARD_CD = SH.HAZARD_CD) WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.SITE_CD = #{siteCd} AND A.INIT_ASSESS_DATE IS NOT NULL AND A.INIT_ASSESS_DATE >= DATE_SUB(STR_TO_DATE(#{occurYmd}, '%Y%m%d'), INTERVAL 3 MONTH) AND A.INIT_ASSESS_DATE < DATE_ADD(STR_TO_DATE(#{occurYmd}, '%Y%m%d'), INTERVAL 1 DAY)
AND A.PROCESS_CD = #{processCd}
AND A.RISK_TYPE_CD = #{riskTypeCd}
AND A.HAZARD_CD = #{hazardCd}
ORDER BY A.INIT_ASSESS_DATE DESC, A.ASSESSMENT_CD DESC

/* Acct01Mapper.selectAcctLinkAssessmentCnt */
SELECT
    COUNT(1)
FROM TB_ACCT_LINK L
WHERE L.CMPNY_CD = #{gvCmpnyCd}
  AND L.SITE_CD = #{siteCd}
  AND L.ACCT_ID = #{acctId}
  AND L.LINK_DOMAIN_CD = 'RISK'
  AND JSON_UNQUOTE(JSON_EXTRACT(L.LINK_KEY_JSON, '$.assessmentCd')) = #{assessmentCd}

/* Acct01Mapper.selectChkptOptions */ SELECT TM.CHKLST_TYPE AS chklstType , FNC_CMM_INFO_SRCH(TM.CMPNY_CD, 'BAIM_VAL', TM.CHKLST_TYPE, 'COM001') AS chklstTypeNm , TM.CHKPT_CD AS chkptCd , TM.CHKPT_NM AS chkptNm , TM.MGMT_USER_CD AS mgmtUserCd , FNC_CMM_INFO_SRCH(TM.CMPNY_CD, 'USER_NM', TM.MGMT_USER_CD, NULL) AS mgmtUserNm FROM TB_CHKPT_TYPE_MGMT TM WHERE TM.CMPNY_CD = #{gvCmpnyCd} AND TM.SITE_CD = #{siteCd} AND TM.USE_YN = 'Y'
AND TM.CHKLST_TYPE = #{chklstType}
AND TM.CHKPT_NM LIKE CONCAT('%', #{chkptNm}, '%')
ORDER BY TM.CHKLST_TYPE, TM.CHKPT_CD

/* Acct01Mapper.selectRiskCategoryOptions */ SELECT 'PROCESS' AS categoryType , BD.BAIM_VAL_D_CD AS code , BD.BAIM_VAL_D_NM AS name , NULL AS parentCode FROM TB_BAIM_VAL_D BD WHERE BD.CMPNY_CD = #{gvCmpnyCd} AND BD.BAIM_VAL_CD = 'COM002' AND BD.USE_YN = 'Y' UNION ALL SELECT 'RISK_TYPE' AS categoryType , RT.RISK_TYPE_CD AS code , RT.RISK_TYPE_NM AS name , RT.PROCESS_CD AS parentCode FROM TB_RISK_TYPE RT WHERE RT.CMPNY_CD = #{gvCmpnyCd} AND RT.USE_YN = 'Y' AND (RT.SITE_CD IS NULL OR RT.SITE_CD = ''
OR RT.SITE_CD = #{siteCd}
)
AND RT.PROCESS_CD = #{processCd}
UNION ALL SELECT 'HAZARD' AS categoryType , SH.HAZARD_CD AS code , SH.HAZARD_NM AS name , SH.RISK_TYPE_CD AS parentCode FROM TB_RISK_SITE_HAZARD SH WHERE SH.CMPNY_CD = #{gvCmpnyCd} AND SH.USE_YN = 'Y' AND (SH.SITE_CD IS NULL OR SH.SITE_CD = ''
OR SH.SITE_CD = #{siteCd}
)
AND SH.RISK_TYPE_CD = #{riskTypeCd}
ORDER BY categoryType, name

/* Acct01Mapper.selectLinkSnapshots */
SELECT
    L.ACCT_ID                                                       AS acctId
  , L.LINK_DOMAIN_CD                                                    AS linkDomainCd
  , FNC_CMM_INFO_SRCH(L.CMPNY_CD, 'SYST_VAL', L.LINK_DOMAIN_CD, 'SYS067') AS linkDomainNm
  , L.LINK_SEQ                                                          AS linkSeq
  , L.LINK_KEY_JSON                                                     AS linkKeyJson
  , L.SNAPSHOT_JSON                                                     AS snapshotJson
  , L.INSERT_NO                                                         AS insertNo
  , DATE_FORMAT(L.INSERT_DATE, '%Y-%m-%d %H:%i')                        AS insertDate
FROM TB_ACCT_LINK L
WHERE L.CMPNY_CD = #{gvCmpnyCd}
  AND L.SITE_CD = #{siteCd}
  AND L.ACCT_ID = #{acctId}

    AND L.LINK_DOMAIN_CD = #{linkDomainCd}

ORDER BY L.LINK_DOMAIN_CD, L.LINK_SEQ

